#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

int addmod(int a, int b) {
    int s = a + b;
    if (s >= MOD) s -= MOD;
    return s;
}

int submod(int a, int b) {
    int s = a - b;
    if (s < 0) s += MOD;
    return s;
}

int mulmod(long long a, long long b) {
    return int((a * b) % MOD);
}

int modpow(int a, long long e = MOD - 2) {
    long long res = 1, cur = a;
    while (e) {
        if (e & 1) res = res * cur % MOD;
        cur = cur * cur % MOD;
        e >>= 1;
    }
    return int(res);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if (!(cin >> n >> k)) return 0;

    // Precompute powers of 2 up to max possible intervals count
    int maxIntervals = n * (n + 1) / 2;
    vector<int> pow2(maxIntervals + 1);
    pow2[0] = 1;
    for (int i = 1; i <= maxIntervals; ++i) {
        pow2[i] = addmod(pow2[i-1], pow2[i-1]);
    }

    // dp[i][j] = number of ways for prefix of length i with max independent set size j
    vector<vector<int>> dp(n + 1, vector<int>(k + 1, 0));
    dp[0][0] = 1;

    // pref[i][j] = sum_{t=0..i} dp[t][j]
    vector<vector<int>> pref(n + 1, vector<int>(k + 1, 0));
    pref[0][0] = 1;
    for (int j = 1; j <= k; ++j) pref[0][j] = 0;

    for (int i = 1; i <= n; ++i) {
        // Case 1: no interval ends at i
        for (int j = 0; j <= k; ++j) {
            dp[i][j] = dp[i-1][j];
        }
        // Case 2: at least one interval ends at i, leftmost start = l
        for (int l = 1; l <= i; ++l) {
            int intervalsEndingAtI_withStartGeL = i - l + 1;
            int waysChooseNonEmpty = submod(pow2[intervalsEndingAtI_withStartGeL], 1);
            int prev = l - 1;
            for (int j = 1; j <= k; ++j) {
                int add = mulmod(waysChooseNonEmpty, pref[prev][j-1]);
                dp[i][j] = addmod(dp[i][j], add);
            }
        }
        // Update prefix sums for this i
        for (int j = 0; j <= k; ++j) {
            pref[i][j] = addmod(pref[i-1][j], dp[i][j]);
        }
    }

    int ans = dp[n][k];
    if (k == 0) ans = 1; // only empty set
    cout << ans << "\n";
    return 0;
}
